import pyomo.environ as pyo

DATA = {
    "appliances": ["washing_machine", "freezer"],
    "inspection_minutes": {"washing_machine": 30, "freezer": 20},
    "fixing_minutes": {"washing_machine": 90, "freezer": 125},
    "inspection_capacity": 5000,
    "schedule_capacity": 20000,
    "earnings": {"washing_machine": 250, "freezer": 375},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.appliances = pyo.Set(initialize=d["appliances"])

    # Decision variables: number of each appliance to repair
    model.repair = pyo.Var(
        model.appliances,
        within=pyo.NonNegativeIntegers,
    )

    # Objective: maximize total earnings
    def obj_rule(m):
        return sum(d["earnings"][i] * m.repair[i] for i in m.appliances)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: inspection time capacity
    def inspection_rule(m):
        return sum(
            d["inspection_minutes"][i] * m.repair[i] for i in m.appliances
        ) <= d["inspection_capacity"]

    model.inspection_capacity = pyo.Constraint(rule=inspection_rule)

    # Constraint: schedule (fixing) time capacity
    def schedule_rule(m):
        return sum(
            d["fixing_minutes"][i] * m.repair[i] for i in m.appliances
        ) <= d["schedule_capacity"]

    model.schedule_capacity = pyo.Constraint(rule=schedule_rule)

    return model

import pyomo.environ as pyo

DATA = {
    # index 0 = washing machine, index 1 = freezer
    "appliances": [0, 1],
    "inspection_time": {0: 30, 1: 20},     # minutes per appliance
    "fixing_time": {0: 90, 1: 125},        # minutes per appliance
    "inspection_capacity": 5000,           # total minutes available
    "schedule_capacity": 20000,            # total minutes available
    "profit": {0: 250, 1: 375},            # dollars earned per appliance
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of appliance types: 0 (washing machine), 1 (freezer)
    model.a = pyo.RangeSet(len(d["appliances"]))

    # Decision: number of each appliance to repair (whole units)
    model.x = pyo.Var(model.a, within=pyo.NonNegativeIntegers)

    # Objective: maximize total earnings
    def obj_rule(m):
        return sum(d["profit"][i] * m.x[i] for i in m.a)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Inspection time capacity: 30*x0 + 20*x1 <= 5000
    def inspection_rule(m, i):
        return d["inspection_time"][i] * m.x[i] <= 0 or True  # placeholder guard
    def inspection_cap_rule(m):
        return (
            sum(d["inspection_time"][i] * m.x[i] for i in m.a)
            <= d["inspection_capacity"]
        )
    model.inspection = pyo.Constraint(rule=inspection_cap_rule)

    # Fixing/schedule time capacity: 90*x0 + 125*x1 <= 20000
    def schedule_cap_rule(m):
        return (
            sum(d["fixing_time"][i] * m.x[i] for i in m.a)
            <= d["schedule_capacity"]
        )
    model.schedule = pyo.Constraint(rule=schedule_cap_rule)

    return model
